import{_ as o,o as t,c as d,a5 as c}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"面向对象思想概述","description":"","frontmatter":{"title":"面向对象思想概述","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","面向对象","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第二部分：面向对象/01-类与对象/面向对象思想概述.md","filePath":"posts/java快速入门/第二部分：面向对象/01-类与对象/面向对象思想概述.md"}'),a={name:"posts/java快速入门/第二部分：面向对象/01-类与对象/面向对象思想概述.md"};function s(r,e,n,_,g,p){return t(),d("div",null,[...e[0]||(e[0]=[c("<div><p><strong>概述</strong> ==计算机设计的目的是帮助我们完成现实中要做的事件，要像现实中一样做事就必须模拟出现在中事物和现实中事物的行为，然后让他们之间发生关系，就如同在现实生活中发生的一样。==</p><p><code>Java</code>语言是一种面向对象的程序设计语言。 面向对象思想是一种程序设计思想。 这里的<strong>对象</strong>泛指现实中一切事物，每种事物都具备自己的<strong>属性</strong>和<strong>行为</strong>。</p><p>面向对象思想就是在计算机程序设计过程中，参照现实中事物，将事物的属性特征、行为特征抽象出来，描述成计算 机事件的设计思想。 它区别于面向过程思想，强调的是通过调用对象的行为来实现功能，而不是自己一步一步的去 操作实现。 <strong>举例</strong> 洗衣服<code>:</code> 面向过程：把衣服脱下来<code>--\\&gt;</code>找一个盆<code>--\\&gt;</code>放点洗衣粉<code>--\\&gt;</code>加点水<code>--\\&gt;</code>浸泡<code>10</code>分钟<code>--\\&gt;</code>揉一揉<code>--\\&gt;</code>清洗衣服<code>--\\&gt;</code>拧干<code>--\\&gt;</code>晾起来 面向对象：把衣服脱下来<code>--\\&gt;</code>打开全自动洗衣机<code>--\\&gt;</code>扔衣服<code>--\\&gt;</code>按钮<code>--\\&gt;</code>晾起来 区别<code>:</code> 面向过程：强调步骤。 面向对象：强调对象，这里的对象就是洗衣机。</p><p><strong>特点</strong> 面向对象思想是一种更符合我们思考习惯的思想，它可以将复杂的事情简单化，并将我们从执行者变成了指挥者。 面向对象的语言中，包含了三大基本特征，即封装、继承和多态。</p></div>",1)])])}const v=o(a,[["render",s]]);export{l as __pageData,v as default};
